// Dual frames are preloaded from the current v13 mappings at battle entry.

const heroArtworkPreloads=new Set();
function preloadHeroArtwork(){
 const frames=s.party.filter(p=>p.id<3||p.id===4).flatMap(p=>['idle','attack','hurt','fallen','cast','guard','walk'].flatMap(state=>spriteFrames(p.id,state)));
 for(const frame of frames)preloadFrameArtwork(frame);
}
function preloadFrameArtwork(frame){
 preloadBattleImage(frame?.asset);
 for(const part of frame?.weaponParts||[]){preloadBattleImage(part.asset);preloadBattleImage(part.maskAsset)}
}
function preloadBattleImage(asset){
 if(!asset||typeof Image!=='function'||heroArtworkPreloads.has(asset))return;
 heroArtworkPreloads.add(asset);
 const image=new Image();
 image.decoding='async';
 image.fetchPriority='low';
 image.onerror=()=>heroArtworkPreloads.delete(asset);
 image.src=asset;
}
function preloadBattleOpening(){
 if(typeof Image!=='function'||globalThis.navigator?.connection?.saveData)return;
 if(!['戰鬥','精英','首領'].includes(currentStage().type))return;
 preloadBattleImage(currentEnvironment().asset);
 for(const p of s.party)if(p.hp>0)for(const state of ['walk','idle'])preloadFrameArtwork(spriteFrames(p.id,state)[0]);
}
function scheduleBattleArtwork(){
 if(typeof Image!=='function'||globalThis.navigator?.connection?.saveData)return;
 const battle=s.auto;
 const warm=()=>{
  if(s.phase!=='battle'||s.auto!==battle)return;
  preloadHeroArtwork();
  preloadWarriorArtwork();
  preloadRangerPaintedArt();
  preloadKnightArtwork();
  preloadMageForms();
  preloadMageBasicArtwork();
  preloadMageDeckEffects();
 };
 // Let the battlefield and its visible images request their assets first.
 if(typeof requestAnimationFrame==='function')requestAnimationFrame(()=>setTimeout(warm,0));
 else warm();
}
